<?php
require_once '../config/database.php';
require_once '../config/session.php';
requireLogin();
if (!in_array(getUserRole(), ['teacher','admin'], true)) { http_response_code(403); exit('Forbidden'); }
$db=getDBConnection(); $teacherId=(int)getUserId(); $message='';
if ($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='publish') {
    $entranceId=(int)($_POST['entrance_exam_id']??0); $publish=(int)($_POST['publish']??0)===1;
    $stmt=$db->prepare('SELECT ee.exam_subject_id FROM entrance_exams ee WHERE ee.id=?'.(getUserRole()==='teacher'?' AND ee.teacher_id=?':''));
    if(getUserRole()==='teacher') $stmt->bind_param('ii',$entranceId,$teacherId); else $stmt->bind_param('i',$entranceId);
    $stmt->execute(); $item=$stmt->get_result()->fetch_assoc(); $stmt->close();
    if($item){
        $esId=(int)$item['exam_subject_id']; $countStmt=$db->prepare('SELECT COUNT(*) AS n FROM questions WHERE exam_subject_id=?'); $countStmt->bind_param('i',$esId); $countStmt->execute(); $count=(int)$countStmt->get_result()->fetch_assoc()['n']; $countStmt->close();
        if($publish && $count<1) $message='Add at least one question before publishing.';
        else { $stmt=$db->prepare('UPDATE exam_subjects SET is_published=?,published_at='.($publish?'NOW()':'NULL').' WHERE id=?'); $p=(int)$publish; $stmt->bind_param('ii',$p,$esId); $stmt->execute(); $stmt->close();
            $stmt=$db->prepare('SELECT exam_id FROM exam_subjects WHERE id=?'); $stmt->bind_param('i',$esId); $stmt->execute(); $examId=(int)$stmt->get_result()->fetch_assoc()['exam_id']; $stmt->close();
            $stmt=$db->prepare('UPDATE exams SET is_published=?'.($publish?',published_at=NOW()':',published_at=NULL').' WHERE id=?'); $stmt->bind_param('ii',$p,$examId); $stmt->execute(); $stmt->close(); $message=$publish?'Entrance exam published for its candidates.':'Entrance exam unpublished.';
        }
    } else $message='Entrance exam not found or not assigned to you.';
}
if ($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='create_candidate') {
    $entranceId=(int)($_POST['entrance_exam_id']??0); $name=trim((string)($_POST['full_name']??'')); $email=trim((string)($_POST['email']??'')); $password=(string)($_POST['password']??'');
    $stmt=$db->prepare('SELECT ee.id,ee.target_class_id FROM entrance_exams ee JOIN exam_subjects es ON es.id=ee.exam_subject_id WHERE es.exam_id=?'.(getUserRole()==='teacher'?' AND ee.teacher_id=?':'').' ORDER BY es.id LIMIT 1');
    if(getUserRole()==='teacher')$stmt->bind_param('ii',$entranceId,$teacherId);else$stmt->bind_param('i',$entranceId);
    $stmt->execute();$target=$stmt->get_result()->fetch_assoc();$stmt->close();
    if(!$target)$message='That entrance exam is not assigned to you.';
    elseif($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<8)$message='Enter a name, valid email and password of at least 8 characters.';
    else try {
        $db->begin_transaction();$hash=password_hash($password,PASSWORD_DEFAULT);$stmt=$db->prepare("INSERT INTO users(email,password,full_name,role) VALUES(?,?,?,'student')");$stmt->bind_param('sss',$email,$hash,$name);$stmt->execute();$studentId=$stmt->insert_id;$stmt->close();$classId=(int)$target['target_class_id'];$rootEntranceId=(int)$target['id'];$stmt=$db->prepare("INSERT INTO entrance_applications(user_id,target_class_id,entrance_exam_id,status) VALUES(?,?,?,'pending')");$stmt->bind_param('iii',$studentId,$classId,$rootEntranceId);$stmt->execute();$stmt->close();$db->commit();$_SESSION['entrance_credential_flash']=['name'=>$name,'email'=>$email,'password'=>$password];$message='Candidate login created. Share the details below with them.';
    } catch(Throwable $e) { try{$db->rollback();}catch(Throwable $ignored){} $message=$e instanceof mysqli_sql_exception&&(int)$e->getCode()===1062?'That email address is already in use.':$e->getMessage(); }
}
$sql='SELECT ee.id,ee.exam_subject_id,e.id exam_id,e.title,c.id class_id,c.name class_name,s.id subject_id,s.name subject_name,es.is_published,(SELECT COUNT(*) FROM questions q WHERE q.exam_subject_id=es.id) question_count,(SELECT COUNT(*) FROM entrance_applications a JOIN entrance_exams ar ON ar.id=a.entrance_exam_id JOIN exam_subjects ars ON ars.id=ar.exam_subject_id WHERE ars.exam_id=e.id AND a.status IN (\'pending\',\'admitted\')) candidate_count FROM entrance_exams ee JOIN exam_subjects es ON es.id=ee.exam_subject_id JOIN exams e ON e.id=es.exam_id JOIN classes c ON c.id=ee.target_class_id JOIN subjects s ON s.id=es.subject_id'.(getUserRole()==='teacher'?' WHERE ee.teacher_id=?':'').' ORDER BY e.created_at DESC,es.id';
$stmt=$db->prepare($sql); if(getUserRole()==='teacher') $stmt->bind_param('i',$teacherId); $stmt->execute(); $exams=$stmt->get_result()->fetch_all(MYSQLI_ASSOC); $stmt->close();
$candidateSql='SELECT MIN(ee.id) AS entrance_id,e.id AS exam_id,e.title,c.name AS class_name,COUNT(*) AS subject_count FROM entrance_exams ee JOIN exam_subjects es ON es.id=ee.exam_subject_id JOIN exams e ON e.id=es.exam_id JOIN classes c ON c.id=ee.target_class_id'.(getUserRole()==='teacher'?' WHERE ee.teacher_id=?':'').' GROUP BY e.id,e.title,c.name ORDER BY MAX(ee.created_at) DESC';
$stmt=$db->prepare($candidateSql); if(getUserRole()==='teacher')$stmt->bind_param('i',$teacherId);$stmt->execute();$candidateExams=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$stmt->close();
$credentialFlash=$_SESSION['entrance_credential_flash']??null; unset($_SESSION['entrance_credential_flash']);
?>
<?php include '../includes/header.php'; ?>
