<div class="card mb-4"><div class="card-header"><h2 class="h5 mb-0"><i class="fas fa-user-plus me-2 text-success"></i>Create a candidate login</h2></div><div class="card-body"><p class="candidate-note mb-3">Candidates remain outside the class roster until an admin admits them. Give the candidate the email and password you set here.</p><form method="post" class="row g-3"><input type="hidden" name="action" value="create_candidate"><div class="col-md-3"><label class="form-label">Entrance exam</label><select class="form-select" name="entrance_exam_id" required><option value="">Choose assigned exam</option><?php foreach($candidateExams as $item): ?><option value="<?php echo (int)$item['exam_id']; ?>"><?php echo htmlspecialchars($item['title'].' — '.$item['class_name'].' ('.$item['subject_count'].' subjects)'); ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label">Candidate name</label><input class="form-control" name="full_name" required></div><div class="col-md-3"><label class="form-label">Email/login</label><input class="form-control" name="email" type="email" required></div><div class="col-md-2"><label class="form-label">Password</label><div class="input-group"><input class="form-control entrance-password" name="password" minlength="8" required><button class="btn btn-outline-primary generate-entrance-password" type="button">Generate</button></div></div><div class="col-md-1 d-flex align-items-end"><button class="btn btn-success w-100" <?php echo !$candidateExams?'disabled':''; ?>>Add</button></div></form><small class="text-muted d-block mt-2">Generated passwords use the normal student format: Famaiis followed by three digits.</small></div></div>
<div class="card"><div class="card-header d-flex justify-content-between align-items-center"><h2 class="h5 mb-0"><i class="fas fa-clipboard-list me-2 text-success"></i>Your assigned exams</h2><span class="badge rounded-pill text-bg-light"><?php echo count($exams); ?> assigned</span></div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Exam</th><th>Target class / subject</th><th>Candidates</th><th>Questions</th><th>Status</th><th>Actions</th></tr></thead><tbody>
<?php foreach($exams as $exam): ?><tr><td><div class="exam-title"><?php echo htmlspecialchars($exam['title']); ?></div><div class="exam-subtitle">Entrance · <?php echo htmlspecialchars($exam['subject_name']); ?></div></td><td><?php echo htmlspecialchars($exam['class_name'].' / '.$exam['subject_name']); ?></td><td><span class="fw-semibold"><?php echo (int)$exam['candidate_count']; ?></span></td><td><?php echo (int)$exam['question_count']; ?></td><td><span class="exam-state <?php echo $exam['is_published']?'live':''; ?>"><i class="fas fa-circle" style="font-size:.45rem"></i><?php echo $exam['is_published']?'Published':'Draft'; ?></span></td><td class="d-flex flex-wrap gap-2"><a class="btn btn-sm btn-primary" href="question_management.php?exam_id=<?php echo (int)$exam['exam_id']; ?>&class_id=<?php echo (int)$exam['class_id']; ?>&subject_id=<?php echo (int)$exam['subject_id']; ?>"><i class="fas fa-pen me-1"></i>Questions</a><a class="btn btn-sm btn-outline-info" href="entrance_exam_results.php?exam_id=<?php echo (int)$exam['exam_id']; ?>"><i class="fas fa-chart-bar me-1"></i>Results</a><form method="post"><input type="hidden" name="action" value="publish"><input type="hidden" name="entrance_exam_id" value="<?php echo (int)$exam['id']; ?>"><input type="hidden" name="publish" value="<?php echo $exam['is_published']?0:1; ?>"><button class="btn btn-sm btn-outline-<?php echo $exam['is_published']?'warning':'success'; ?>"><?php echo $exam['is_published']?'Unpublish':'Publish'; ?></button></form></td></tr><?php endforeach; ?>
<?php if(!$exams): ?><tr><td colspan="6" class="text-muted">No entrance exams assigned to you.</td></tr><?php endif; ?></tbody></table></div></div></div>
<script>document.querySelectorAll('.generate-entrance-password').forEach(function(button){button.addEventListener('click',function(){var input=button.closest('.input-group').querySelector('.entrance-password');input.value='Famaiis'+(100+crypto.getRandomValues(new Uint32Array(1))[0]%900);input.type='text';input.focus();});});</script>
